#include <iostream>
#include <iomanip>

// 1. Khai bao nguyen mau ham (Function prototypes)
double luythua(double x, int n);
void inKetQua(double coSo, int soMu, double ketQua);

int main() {
    double x = 0.0;
    int n = 0;
    if (std::cin >> x >> n) {
        double kq = luythua(x, n);
        inKetQua(x, n, kq);
    }
    return 0;
}

// 2. Dinh nghia ham luy thua (Function definition)
double luythua(double x, int n) {
    double kq = 1.0;
    for (int i = 1; i <= n; ++i) {
        kq *= x;
    }
    return kq;
}

// 3. Dinh nghia ham kieu void
void inKetQua(double coSo, int soMu, double ketQua) {
    std::cout << std::fixed << std::setprecision(2);
    std::cout << coSo << "^" << soMu << " = " << ketQua << std::endl;
}

#include <iostream>

// Dinh nghia truoc ham tro giup de khong can prototype rieng
void inkitu(int n, char c) {
    for (int i = 0; i < n; ++i) {
        std::cout << c;
    }
    std::cout << std::endl;
}

// Ham tinh giai thua de quy minh hoa loi goi de quy va bieu thuc
long long giaiThua(int n) {
    if (n <= 1) {
        return 1;
    }
    return n * giaiThua(n - 1); // Loi goi de quy nam trong bieu thuc
}

int main() {
    int soLuong = 0;
    char kyTu = ' ';
    if (std::cin >> soLuong >> kyTu) {
        // Goi ham inkitu voi tham doi thuc su la bien va hang
        inkitu(soLuong, kyTu);

        // Goi ham giaiThua ben trong bieu thuc in
        std::cout << "Giai thua: " << giaiThua(soLuong) << std::endl;
    }
    return 0;
}
